package com.sponsormatch.controller;
import com.sponsormatch.dto.CreatorDtos.*; import com.sponsormatch.service.CreatorService; import jakarta.validation.Valid; import lombok.RequiredArgsConstructor; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.web.bind.annotation.*; import java.math.BigDecimal; import java.util.List;
@RestController @RequestMapping("/api/creators") @RequiredArgsConstructor public class CreatorController {private final CreatorService service; @PostMapping("/profile") public CreatorResponse create(@AuthenticationPrincipal Long id,@Valid @RequestBody ProfileRequest r){return service.create(id,r);}@PutMapping("/profile") public CreatorResponse update(@AuthenticationPrincipal Long id,@Valid @RequestBody ProfileRequest r){return service.update(id,r);}@GetMapping("/profile") public CreatorResponse mine(@AuthenticationPrincipal Long id){return service.mine(id);}@GetMapping("/{id}") public CreatorResponse get(@PathVariable Long id){return service.byId(id);}@GetMapping("/search") public List<CreatorResponse> search(@RequestParam(required=false)String q,@RequestParam(required=false)String category,@RequestParam(required=false)String platform,@RequestParam(required=false)String location,@RequestParam(required=false)Long minFollowers,@RequestParam(required=false)Long maxFollowers,@RequestParam(required=false)BigDecimal minEngagement,@RequestParam(required=false)BigDecimal minPrice,@RequestParam(required=false)BigDecimal maxPrice){return service.search(q,category,platform,location,minFollowers,maxFollowers,minEngagement,minPrice,maxPrice);}}
